(3275912, 457708, 71741, '<td valign="top">Not to pick this image apart but a few things could have helped a lot.  There is a lot going on in the background, I would have cropped in much tighter or used a bigger aperture to the the back out of focus.  It looks like a polarizer would have helped here to eliminate the reflections on the tombstone as well.</td>', 'Not to pick this image apart but a few things could have helped a lot.  There is a lot going on in the background, I would have cropped in much tighter or used a bigger aperture to the the back out of focus.  It looks like a polarizer would have helped here to eliminate the reflections on the tombstone as well.', '2007-01-24 13:45:41.000000', NULL, 1),
(3275944, 455475, 71834, '<td valign="top">You just can''t help noticing the rotation from the vertical</td>', 'You just can''t help noticing the rotation from the vertical', '2007-01-24 13:54:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3275949, 457459, 71834, '<td valign="top">spoilt by the lens distortion or some shoddy building in the painted layers at the top</td>', 'spoilt by the lens distortion or some shoddy building in the painted layers at the top', '2007-01-24 13:56:01.000000', NULL, 1),
(3275959, 456981, 71834, '<td valign="top">Rotation is off and some distortion. For such a simple stark image they need to be spot on.</td>', 'Rotation is off and some distortion. For such a simple stark image they need to be spot on.', '2007-01-24 13:59:37.000000', NULL, 1),
(3276024, 456956, 71834, '<td valign="top">Needs another light source to take out the shadows</td>', 'Needs another light source to take out the shadows', '2007-01-24 14:13:44.000000', NULL, 1),
(3276078, 457698, 71834, '<td valign="top">Shame about that spot of moisture on the yolk. A nice strong simple composition.</td>', 'Shame about that spot of moisture on the yolk. A nice strong simple composition.', '2007-01-24 14:22:27.000000', NULL, 1),
(3276084, 454950, 71834, '<td valign="top">Nice idea, but the laser picks up every bit of dust in the air. Needs a cleanroom or more editing allowed.</td>', 'Nice idea, but the laser picks up every bit of dust in the air. Needs a cleanroom or more editing allowed.', '2007-01-24 14:23:38.000000', NULL, 1),
(3276093, 456190, 71834, '<td valign="top">Looks a little muddled with both sharp and motion blurred persons. Perhaps a slower shutter speed to blur them all would have been better.</td>', 'Looks a little muddled with both sharp and motion blurred persons. Perhaps a slower shutter speed to blur them all would have been better.', '2007-01-24 14:24:55.000000', NULL, 1),
(3276095, 456184, 71834, '<td valign="top">The eye immediately picks out the geometry that''s slightly off, centration oand rotation. If those were perfect it would be great.</td>', 'The eye immediately picks out the geometry that''s slightly off, centration oand rotation. If those were perfect it would be great.', '2007-01-24 14:25:08.000000', NULL, 1),
(3276105, 457278, 71834, '<td valign="top">Little too dark in the sky - there''s another comet image in the challenge that''s just that bit better.</td>', 'Little too dark in the sky - there''s another comet image in the challenge that''s just that bit better.', '2007-01-24 14:27:06.000000', NULL, 1),
(3276109, 457606, 71834, '<td valign="top">I like the composition, but it''s let down by the overexposure of the lips and skin.</td>', 'I like the composition, but it''s let down by the overexposure of the lips and skin.', '2007-01-24 14:27:53.000000', NULL, 1),
(3276113, 456600, 71834, '<td valign="top">I don''t like the smaller, thinner blobs. I''d have given it +1 without them.</td>', 'I don''t like the smaller, thinner blobs. I''d have given it +1 without them.', '2007-01-24 14:29:13.000000', NULL, 1),
(3276116, 456071, 71834, '<td valign="top">Great title. Shame about the clutter in the lower left of the image.</td>', 'Great title. Shame about the clutter in the lower left of the image.', '2007-01-24 14:29:54.000000', NULL, 1),
(3276117, 457511, 71834, '<td valign="top">Might have been better with the model''s hair tied tightly back. Then the water effect would have been greater.</td>', 'Might have been better with the model''s hair tied tightly back. Then the water effect would have been greater.', '2007-01-24 14:30:00.000000', NULL, 1),
(3276120, 456219, 71834, '<td valign="top">Might work well as a long exposure motion blur type image.</td>', 'Might work well as a long exposure motion blur type image.', '2007-01-24 14:30:24.000000', NULL, 1),
(3276125, 456085, 54446, '<td valign="top">horizon not level.</td>', 'horizon not level.', '2007-01-24 14:32:57.000000', NULL, 1),
(3276128, 456986, 67258, '<td valign="top">The shape of the spiralling fire escape, with it''s accompanying shadow is very pleasing,and it looks particularly good against the teracotta coloured rendering.  The shadows of the tree do,''though detract from the over-all effect</td>', 'The shape of the spiralling fire escape, with it''s accompanying shadow is very pleasing,and it looks particularly good against the teracotta coloured rendering.  The shadows of the tree do,''though detract from the over-all effect', '2007-01-24 14:34:40.000000', NULL, 1),
(3276135, 457662, 67258, '<td valign="top">Funny and frightening at the same time.  Love the black humour, and photographically good too.</td>', 'Funny and frightening at the same time.  Love the black humour, and photographically good too.', '2007-01-24 14:39:16.000000', NULL, 1),
(3276141, 456985, 67258, '<td valign="top">This reminds me of an excellent (although seriously scary) children''s book called Marianne Dreams.  Love the lighting - light into dark, reality into fantasy, normality into nightmare...</td>', 'This reminds me of an excellent (although seriously scary) children''s book called Marianne Dreams.  Love the lighting - light into dark, reality into fantasy, normality into nightmare...', '2007-01-24 14:42:06.000000', NULL, 1),
(3276145, 456896, 67258, '<td valign="top">A great one for the family album - but far more than just a snapshot, too.  My favourite so far.  Hope the tooth fairy visited...</td>', 'A great one for the family album - but far more than just a snapshot, too.  My favourite so far.  Hope the tooth fairy visited...', '2007-01-24 14:44:09.000000', NULL, 1),
(3276153, 456071, 67258, '<td valign="top">What a wonderful capture!</td>', 'What a wonderful capture!', '2007-01-24 14:46:12.000000', NULL, 1),
(3276156, 456507, 67258, '<td valign="top">Yep, I can relate to this one!</td>', 'Yep, I can relate to this one!', '2007-01-24 14:47:08.000000', NULL, 1),
(3276166, 456581, 67258, '<td valign="top">Black and white was a good choice.  The leading lines of the receding brickwork make for a good strong feature, and the lighting is spot on.</td>', 'Black and white was a good choice.  The leading lines of the receding brickwork make for a good strong feature, and the lighting is spot on.', '2007-01-24 14:48:27.000000', NULL, 1),
(3276171, 456956, 67258, '<td valign="top">Alice? Did you find Wonderland? Excellent work.</td>', 'Alice? Did you find Wonderland? Excellent work.', '2007-01-24 14:49:20.000000', NULL, 1),
(3276174, 456193, 67258, '<td valign="top">Pleasingly composed.</td>', 'Pleasingly composed.', '2007-01-24 14:49:44.000000', NULL, 1),
(3276179, 457694, 67258, '<td valign="top">I would normally agree that it is best for the photagrapher to get down to the viewpoint of the subject, but in this instance I wonder if looking down on the little hand might have given more of an impression of a small child?</td>', 'I would normally agree that it is best for the photagrapher to get down to the viewpoint of the subject, but in this instance I wonder if looking down on the little hand might have given more of an impression of a small child?', '2007-01-24 14:51:25.000000', NULL, 1),
(3276182, 457447, 67258, '<td valign="top">Ouch - right place, right time!</td>', 'Ouch - right place, right time!', '2007-01-24 14:51:49.000000', NULL, 1),
(3276188, 457028, 67258, '<td valign="top">As the photo finaly revealed itself, I was quite glad to see this was a closed lavatory bowl! Mildly humourous, but not an appealing image, and not keen on the dof.</td>', 'As the photo finaly revealed itself, I was quite glad to see this was a closed lavatory bowl! Mildly humourous, but not an appealing image, and not keen on the dof.', '2007-01-24 14:53:58.000000', NULL, 1),
(3276190, 456000, 67258, '<td valign="top">Even ex-c-ited...</td>', 'Even ex-c-ited...', '2007-01-24 14:54:47.000000', NULL, 1),
(3276194, 457689, 67258, '<td valign="top">An intelectually good take on the challenge, but dull as aphotograph viewed in its own right.</td>', 'An intelectually good take on the challenge, but dull as aphotograph viewed in its own right.', '2007-01-24 14:55:45.000000', NULL, 1),
(3276200, 457527, 67258, '<td valign="top">A concept that has been done by others in the challenge, too.  But this is the best execution of it that I have seen so far.  Good work.</td>', 'A concept that has been done by others in the challenge, too.  But this is the best execution of it that I have seen so far.  Good work.', '2007-01-24 14:57:38.000000', NULL, 1),
(3276201, 456085, 67258, '<td valign="top">Lovely framing.</td>', 'Lovely framing.', '2007-01-24 14:58:01.000000', NULL, 1),
(3276207, 457512, 67258, '<td valign="top">This makes the brain work overtime! Love the composition.</td>', 'This makes the brain work overtime! Love the composition.', '2007-01-24 14:58:51.000000', NULL, 1),
(3276208, 455126, 67258, '<td valign="top">Wow!</td>', 'Wow!', '2007-01-24 14:59:04.000000', NULL, 1),
(3276210, 457039, 67258, '<td valign="top">Well spotted, and very pleasingly presented.  Simple, but effective - right up my street.</td>', 'Well spotted, and very pleasingly presented.  Simple, but effective - right up my street.', '2007-01-24 14:59:43.000000', NULL, 1),
(3276214, 457123, 67258, '<td valign="top">I like the idea very much, but do find the lighting very harsh.</td>', 'I like the idea very much, but do find the lighting very harsh.', '2007-01-24 15:00:39.000000', NULL, 1),
(3276235, 457030, 67258, '<td valign="top">One of my girlfriends was beaten up by a gang of four ''hoodies'' last night - she is black and blue today.  I can feel the palpable sense of fear and threat.  A well staged and executed concept, and a 10 from me.</td>', 'One of my girlfriends was beaten up by a gang of four ''hoodies'' last night - she is black and blue today.  I can feel the palpable sense of fear and threat.  A well staged and executed concept, and a 10 from me.', '2007-01-24 15:05:45.000000', NULL, 1),
(3276238, 456183, 67258, '<td valign="top">Yep, I like this one!</td>', 'Yep, I like this one!', '2007-01-24 15:06:19.000000', NULL, 1),
(3276248, 454581, 62939, '<td valign="top">if this was MUCH sharper, I would give it a 9, great image suffers from the blurriness.</td>', 'if this was MUCH sharper, I would give it a 9, great image suffers from the blurriness.', '2007-01-24 15:08:55.000000', NULL, 1),
(3276250, 456889, 67258, '<td valign="top">That is desperately sad - if rescue wasn''t going to happen, let''s hope it was a quick ''exit''.  Despite the distress you must have been in presented with this scene, you have taken a thoughtful photograph.</td>', 'That is desperately sad - if rescue wasn''t going to happen, let''s hope it was a quick ''exit''.  Despite the distress you must have been in presented with this scene, you have taken a thoughtful photograph.', '2007-01-24 15:09:51.000000', NULL, 1),
(3276251, 457593, 62939, '<td valign="top">nice location, I would have liked a more simple composition though</td>', 'nice location, I would have liked a more simple composition though', '2007-01-24 15:09:52.000000', NULL, 1),
(3276292, 455488, 34938, '<td valign="top">This has to be a contender...perfect</td>', 'This has to be a contender...perfect', '2007-01-24 15:25:02.000000', NULL, 1),
(3276298, 457307, 34938, '<td valign="top">I like the simplicity of this and the framing of the tunnel</td>', 'I like the simplicity of this and the framing of the tunnel', '2007-01-24 15:26:50.000000', NULL, 1),
(3276307, 457114, 34938, '<td valign="top">I don''t think you can do this in basic editing, but I will give you the benefit of the doubt,,,as far as the image is concerned it''s a nice composition, but I don''t see how it relates to the challenge without your title</td>', 'I don''t think you can do this in basic editing, but I will give you the benefit of the doubt,,,as far as the image is concerned it''s a nice composition, but I don''t see how it relates to the challenge without your title', '2007-01-24 15:28:04.000000', NULL, 1),
(3276311, 456986, 34938, '<td valign="top">wonderful, strong colours and sharpness...I would have cropped out the right hand side and entered a square crop, but that''s just me...</td>', 'wonderful, strong colours and sharpness...I would have cropped out the right hand side and entered a square crop, but that''s just me...', '2007-01-24 15:29:03.000000', NULL, 1),
(3276313, 454679, 57584, '<td valign="top">TOTALLY black .... wis</td>', 'TOTALLY black .... wis', '2007-01-24 15:30:20.000000', NULL, 1),
(3276318, 455628, 34938, '<td valign="top">I like the processing and the comp...I just wish we could see just a little more of her face as it looks like just hair...very good image for the challenge, I hope you do well with this</td>', 'I like the processing and the comp...I just wish we could see just a little more of her face as it looks like just hair...very good image for the challenge, I hope you do well with this', '2007-01-24 15:31:10.000000', NULL, 1),
(3276323, 455791, 34938, '<td valign="top">awesome fisheye...hope the voters are kind and you do well with this</td>', 'awesome fisheye...hope the voters are kind and you do well with this', '2007-01-24 15:32:25.000000', NULL, 1),
(3276329, 457174, 34938, '<td valign="top">nice composition...colour are good</td>', 'nice composition...colour are good', '2007-01-24 15:34:37.000000', NULL, 1),
(3276330, 456581, 30982, '<td valign="top">Good perspective and exposure.  I like the wire running along the floor for some reason.</td>', 'Good perspective and exposure.  I like the wire running along the floor for some reason.', '2007-01-24 15:34:48.000000', NULL, 1),
(3276333, 457568, 30982, '<td valign="top">Maybe just a bit too high key - takes away some of what looks to be interesting texture.  Still, well seen.</td>', 'Maybe just a bit too high key - takes away some of what looks to be interesting texture.  Still, well seen.', '2007-01-24 15:35:32.000000', NULL, 1),
(3276335, 455720, 34938, '<td valign="top">I like the image overall...not sure if the frame is legal, but I will give you the benefit of the doubt</td>', 'I like the image overall...not sure if the frame is legal, but I will give you the benefit of the doubt', '2007-01-24 15:36:10.000000', NULL, 1),
(3276336, 455644, 30982, '<td valign="top">Lovely late day capture.  Not a hugely strong tie to the challenge, but it''s there for those who look.</td>', 'Lovely late day capture.  Not a hugely strong tie to the challenge, but it''s there for those who look.', '2007-01-24 15:36:17.000000', NULL, 1),
(3276339, 455628, 30982, '<td valign="top">Very nice interpretation.  I like the contrast of youth against the deceased - sepia serves this well.</td>', 'Very nice interpretation.  I like the contrast of youth against the deceased - sepia serves this well.', '2007-01-24 15:38:16.000000', NULL, 1),
(3276341, 457511, 30982, '<td valign="top">Good stop motion!  A bit overexposed on the face which draws attention away from the shapes formed by the water.</td>', 'Good stop motion!  A bit overexposed on the face which draws attention away from the shapes formed by the water.', '2007-01-24 15:39:24.000000', NULL, 1),
(3276345, 457109, 30982, '<td valign="top">Ewww.  But funny and I like the red reflection in the droplets.</td>', 'Ewww.  But funny and I like the red reflection in the droplets.', '2007-01-24 15:39:52.000000', NULL, 1),
(3276368, 457233, 13624, '<td valign="top">Great image, but the subject lacks intensity.</td>', 'Great image, but the subject lacks intensity.', '2007-01-24 15:48:01.000000', NULL, 1),
(3276391, 457568, 5746, '<td valign="top">I would like to see the whole exit. I guess it is some kind of a door, but I miss more context.</td>', 'I would like to see the whole exit. I guess it is some kind of a door, but I miss more context.', '2007-01-24 15:58:20.000000', NULL, 1),
(3276393, 456184, 5746, '<td valign="top">I like the perspective and colour here. The exit is distant, and yet it takes a while to realize it fits the challenge.</td>', 'I like the perspective and colour here. The exit is distant, and yet it takes a while to realize it fits the challenge.', '2007-01-24 15:59:23.000000', NULL, 1),
(3276405, 456985, 5746, '<td valign="top">I love thi unusual perspective on the challenge  theme. Very creative. A bit too dark IMHO.</td>', 'I love thi unusual perspective on the challenge  theme. Very creative. A bit too dark IMHO.', '2007-01-24 16:02:41.000000', NULL, 1),
(3276416, 457645, 28172, '<td valign="top">Beautiful vibrant colors!  Really lovely shot! 10</td>', 'Beautiful vibrant colors!  Really lovely shot! 10', '2007-01-24 16:04:53.000000', NULL, 1),
(3276417, 456600, 5746, '<td valign="top">The fries are missing :)</td>', 'The fries are missing :)', '2007-01-24 16:04:55.000000', NULL, 1),
(3276443, 456071, 66201, '<td valign="top">Oh very sweet!! Nice title and good composition.</td>', 'Oh very sweet!! Nice title and good composition.', '2007-01-24 16:11:25.000000', NULL, 1),
(3276493, 456183, 66201, '<td valign="top">I like this so much. I love the fact that there is an untold story happening here (posed or not). Lovely sepia and use of movement blur. I would have just given a smidge more breathing space above her head.8</td>', 'I like this so much. I love the fact that there is an untold story happening here (posed or not). Lovely sepia and use of movement blur. I would have just given a smidge more breathing space above her head.8', '2007-01-24 16:21:03.000000', NULL, 1),
(3276496, 456581, 66201, '<td valign="top">Nice atmoshpere and a sense of story going on... I like the mops and stuff getting in the way to add context and interest.</td>', 'Nice atmoshpere and a sense of story going on... I like the mops and stuff getting in the way to add context and interest.', '2007-01-24 16:21:23.000000', NULL, 1),
(3276523, 456985, 69387, '<td valign="top">Great idea. I wish I could do this sometimes, I''ll have a whole lot of photos ligned up. I would have given this a higher rating if not for the bottom part being way too dark.</td>', 'Great idea. I wish I could do this sometimes, I''ll have a whole lot of photos ligned up. I would have given this a higher rating if not for the bottom part being way too dark.', '2007-01-24 16:29:28.000000', NULL, 1),
(3276525, 457718, 69387, '<td valign="top">Good clarity. Is it me or is the photo a bit tilted?</td>', 'Good clarity. Is it me or is the photo a bit tilted?', '2007-01-24 16:29:57.000000', NULL, 1),
(3276528, 457447, 69387, '<td valign="top">Yikes! Nice idea, it would have been a lot less title dependent if I saw an exit sign above.</td>', 'Yikes! Nice idea, it would have been a lot less title dependent if I saw an exit sign above.', '2007-01-24 16:30:35.000000', NULL, 1),
(3276530, 456889, 43565, '<td valign="top">Looks like a call needs to be made to whoever is in charge of animal protection.</td>', 'Looks like a call needs to be made to whoever is in charge of animal protection.', '2007-01-24 16:30:49.000000', NULL, 1),
