(3279920, 457639, 66201, '<td valign="top">I love the red, green, grey palette. Well composed and a lovely image to just look at for its own sake.</td>', 'I love the red, green, grey palette. Well composed and a lovely image to just look at for its own sake.', '2007-01-25 04:23:20.000000', NULL, 1),
(3279925, 457459, 66201, '<td valign="top">I like the colour and unusual take on a door... I think I would have cropped the curb off and taken it from the grey only. The problem with this image in a dual challenge of entrance and exit, it could be either. If the Entrance challenge had not been running concurrently this would have made more impact.</td>', 'I like the colour and unusual take on a door... I think I would have cropped the curb off and taken it from the grey only. The problem with this image in a dual challenge of entrance and exit, it could be either. If the Entrance challenge had not been running concurrently this would have made more impact.', '2007-01-25 04:25:05.000000', NULL, 1),
(3279927, 456986, 66201, '<td valign="top">I like the shadow patterns and the brown/grey colours. Just a bit ambiguous - apart from your title - to know whether this is an entrance or exit, since it serves as both.</td>', 'I like the shadow patterns and the brown/grey colours. Just a bit ambiguous - apart from your title - to know whether this is an entrance or exit, since it serves as both.', '2007-01-25 04:26:49.000000', NULL, 1),
