INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3290976, 457707, 70999, '<td valign="top">Good effort but I can''t help but feel disappointed that there is not much to see outside!</td>', 'Good effort but I can''t help but feel disappointed that there is not much to see outside!', '2007-01-27 13:26:09.000000', NULL, 1),
(3290979, 455644, 70999, '<td valign="top">The way the image is not centered in the border is distracting.  Nice shot though.</td>', 'The way the image is not centered in the border is distracting.  Nice shot though.', '2007-01-27 13:27:04.000000', NULL, 1),
(3290982, 456421, 65319, '<td valign="top">The detail and simplicity of this photo has an almost Zen-like quality.  10.</td>', 'The detail and simplicity of this photo has an almost Zen-like quality.  10.', '2007-01-27 13:28:32.000000', NULL, 1),
(3290985, 455497, 70999, '<td valign="top">Not exactly inspiring I''m afraid.</td>', 'Not exactly inspiring I''m afraid.', '2007-01-27 13:29:14.000000', NULL, 1),
(3290987, 456889, 65319, '<td valign="top">I''m very disappointed to see such an inhumane portrayal of an animal in a DPC challenge and feel this type of photography adds very little to the quality of this website.  1.</td>', 'I''m very disappointed to see such an inhumane portrayal of an animal in a DPC challenge and feel this type of photography adds very little to the quality of this website.  1.', '2007-01-27 13:30:10.000000', NULL, 1),
(3290988, 456460, 70999, '<td valign="top">I find the shadow very distracting in this one.  Perhaps a tighter crop?</td>', 'I find the shadow very distracting in this one.  Perhaps a tighter crop?', '2007-01-27 13:30:13.000000', NULL, 1),
(3290992, 456850, 70999, '<td valign="top">Nice effect.</td>', 'Nice effect.', '2007-01-27 13:31:13.000000', NULL, 1),
(3290995, 456281, 70999, '<td valign="top">Struggling to see the connection I''m afraid.</td>', 'Struggling to see the connection I''m afraid.', '2007-01-27 13:31:33.000000', NULL, 1),
(3290996, 457517, 65319, '<td valign="top">PERFECT!!!!!!!!  My favorite in this challenge!!!!  10.</td>', 'PERFECT!!!!!!!!  My favorite in this challenge!!!!  10.', '2007-01-27 13:31:37.000000', NULL, 1),
(3291001, 457760, 65319, '<td valign="top">How lovely.  Reminds me of the movie "Narnia".  9.</td>', 'How lovely.  Reminds me of the movie "Narnia".  9.', '2007-01-27 13:33:05.000000', NULL, 1),
(3291008, 457580, 70999, '<td valign="top">I think this would work better with the footstops pointing away from the viewpoint.  As it is it looks closer to an approach than an exit.  There seems to be no connection with the other elements present in the picture.</td>', 'I think this would work better with the footstops pointing away from the viewpoint.  As it is it looks closer to an approach than an exit.  There seems to be no connection with the other elements present in the picture.', '2007-01-27 13:34:36.000000', NULL, 1),
(3291018, 457376, 70999, '<td valign="top">Don''t really see how this is an "exit".  And I won''t be the first to say "too small" I''m guessing.  But I like  the effect of the shadows across the road.</td>', 'Don''t really see how this is an "exit".  And I won''t be the first to say "too small" I''m guessing.  But I like  the effect of the shadows across the road.', '2007-01-27 13:38:43.000000', NULL, 1),
(3291021, 456981, 70999, '<td valign="top">Well exposed and good focus, but not interesting enough I''m afraid.</td>', 'Well exposed and good focus, but not interesting enough I''m afraid.', '2007-01-27 13:40:49.000000', NULL, 1),
(3291034, 456986, 70999, '<td valign="top">Wouldn''t it be nice if you could chop down that damn tree? :)</td>', 'Wouldn''t it be nice if you could chop down that damn tree? :)', '2007-01-27 13:45:38.000000', NULL, 1),
(3291066, 457766, 70999, '<td valign="top">Nice title :).</td>', 'Nice title :).', '2007-01-27 13:52:18.000000', NULL, 1),
