(3292672, 456320, 68504, '<td valign="top">Eeee, I like the 2 legs that suggest a dog. Nice patterns in building and canopy.</td>', 'Eeee, I like the 2 legs that suggest a dog. Nice patterns in building and canopy.', '2007-01-28 00:42:35.000000', NULL, 1),
(3292677, 454611, 68504, '<td valign="top">Like the idea, and the pattern is intriguing, but needs a little more definition to realized its potential.</td>', 'Like the idea, and the pattern is intriguing, but needs a little more definition to realized its potential.', '2007-01-28 00:44:27.000000', NULL, 1),
(3292680, 457517, 68504, '<td valign="top">Nice colonnade:  lighted shrubbery at end is a little dissapointing after the magnificence of the columns and ceiling. Good perspective.</td>', 'Nice colonnade:  lighted shrubbery at end is a little dissapointing after the magnificence of the columns and ceiling. Good perspective.', '2007-01-28 00:47:38.000000', NULL, 1),
(3292694, 456889, 68504, '<td valign="top">Gives me grief.  Well photographed - colours in trash pile bring out colours in horse/donkey whom I assume is not moribund, but has a very hard life.</td>', 'Gives me grief.  Well photographed - colours in trash pile bring out colours in horse/donkey whom I assume is not moribund, but has a very hard life.', '2007-01-28 00:54:28.000000', NULL, 1),
(3292699, 455644, 68504, '<td valign="top">Well coloured and composed. (Title refer to the rivers of Lethe?). Contrast between blurred flow and etched outline of trees very pleasing.</td>', 'Well coloured and composed. (Title refer to the rivers of Lethe?). Contrast between blurred flow and etched outline of trees very pleasing.', '2007-01-28 00:57:46.000000', NULL, 1),
(3292705, 456600, 68504, '<td valign="top">Well composed and photographed.  Like the illusion of bottle standing on ketchup''s egress, and the glopping of ketchup inside the bottle.</td>', 'Well composed and photographed.  Like the illusion of bottle standing on ketchup''s egress, and the glopping of ketchup inside the bottle.', '2007-01-28 01:01:03.000000', NULL, 1),
(3292707, 455149, 68504, '<td valign="top">Bit of a stretch, but you made it and I got it.</td>', 'Bit of a stretch, but you made it and I got it.', '2007-01-28 01:03:43.000000', NULL, 1),
(3292711, 455488, 68504, '<td valign="top">That''s not Murray, it''s Charlie!  And he has some explaining to do.</td>', 'That''s not Murray, it''s Charlie!  And he has some explaining to do.', '2007-01-28 01:05:34.000000', NULL, 1),
(3292716, 456183, 68504, '<td valign="top">It''s good - dirty snow,anonymous traffic, dreadnaughts(?) and ragged jeans, and dirty snow-coloured sepia.</td>', 'It''s good - dirty snow,anonymous traffic, dreadnaughts(?) and ragged jeans, and dirty snow-coloured sepia.', '2007-01-28 01:08:58.000000', NULL, 1),
(3292723, 457511, 68504, '<td valign="top">Not getting the stargate (lower middle?) nor the orientation, but the water, hair and face are sensuous, visually. (Black border too heavy, detracts from hair instead of complementing it).</td>', 'Not getting the stargate (lower middle?) nor the orientation, but the water, hair and face are sensuous, visually. (Black border too heavy, detracts from hair instead of complementing it).', '2007-01-28 01:13:42.000000', NULL, 1),
