(3292728, 456507, 68504, '<td valign="top">Apt and crisp.</td>', 'Apt and crisp.', '2007-01-28 01:16:47.000000', NULL, 1),
(3292731, 456297, 68504, '<td valign="top">Stunning mirroring of shapes above and below, and subtle meandering of estuary.   Like the yellow green on left horizon.  (Okay, I''m not the only one to wonder what it would be like if the horizon were leveled).</td>', 'Stunning mirroring of shapes above and below, and subtle meandering of estuary.   Like the yellow green on left horizon.  (Okay, I''m not the only one to wonder what it would be like if the horizon were leveled).', '2007-01-28 01:21:46.000000', NULL, 1),
