(3305547, 455488, 34659, '<td valign="top">Well done!  Very cool!  Great editing, presentation, score, &amp; finish.  :-)</td>', 'Well done!  Very cool!  Great editing, presentation, score, & finish.  :-)', '2007-01-31 00:45:58.000000', NULL, 0),
(3305548, 456507, 56880, '<td valign="top">This was one of my top 4; an original idea executed well.  It''s too bad the more voters didn''t see it this way.</td>', 'This was one of my top 4; an original idea executed well.  It''s too bad the more voters didn''t see it this way.', '2007-01-31 00:46:07.000000', NULL, 0),
