(3305584, 455126, 22537, '<td valign="top">This is simply AMAZING!! I envy your for seeing this but I appreciate you seeing this for us.  Congrats on the moment and the recognition of a special photo.</td>', 'This is simply AMAZING!! I envy your for seeing this but I appreciate you seeing this for us.  Congrats on the moment and the recognition of a special photo.', '2007-01-31 00:52:08.000000', NULL, 0),
(3305603, 455286, 65319, '<td valign="top">I cannot believe where this photo placed. You were robbed!</td>', 'I cannot believe where this photo placed. You were robbed!', '2007-01-31 00:55:55.000000', NULL, 0),
