(3317629, 455488, 2553, '<td valign="top">Congratulations!  I''d love to get inside your head.  Your creativity always astounds me.</td>', 'Congratulations!  I''d love to get inside your head.  Your creativity always astounds me.', '2007-02-02 06:05:02.000000', NULL, 0),
(3318085, 455488, 15266, '<td valign="top">Great shot, Cole.  I love your imagination.   :)</td>', 'Great shot, Cole.  I love your imagination.   :)', '2007-02-02 10:06:38.000000', NULL, 0),
(3319582, 456986, 26679, '<td valign="top">Congratulations on your first ribon....</td>', 'Congratulations on your first ribon....', '2007-02-02 16:47:09.000000', NULL, 0),
(3320477, 457517, 36328, '<td valign="top">now for something different...... You suck man!<br/> <br/>Just kidding, your so hot right now I can feel it in MK. You trail blazing S.O.B.<br/> <br/>Where is this? Stowe Gardens or somewhere similar? I always take crap/dull pictures at places like that, but this is cool. Also, HDR? Loving the contrasty look.</td>', 'now for something different...... You suck man! Just kidding, your so hot right now I can feel it in MK. You trail blazing S.O.B. Where is this? Stowe Gardens or somewhere similar? I always take crap/dull pictures at places like that, but this is cool. Also, HDR? Loving the contrasty look.', '2007-02-02 19:50:34.000000', NULL, 0),
(3321331, 455126, 47152, '<td valign="top">This night photo has a majestic ambience to it.  The olny thing I believe could be left out is that white triangular point towards the bottom.  It distracts the eye from the main focus.</td>', 'This night photo has a majestic ambience to it.  The olny thing I believe could be left out is that white triangular point towards the bottom.  It distracts the eye from the main focus.', '2007-02-03 00:26:36.000000', NULL, 0),
(3321777, 455126, 29658, '<td valign="top">I would like to have a personal conversation with people who scored 4, 5 and 6 such a picture. And the 2 and 3? Well... Mmmm..</td>', 'I would like to have a personal conversation with people who scored 4, 5 and 6 such a picture. And the 2 and 3? Well... Mmmm..', '2007-02-03 05:47:14.000000', NULL, 0),
(3322235, 456986, 7743, '<td valign="top">Love the symmetry created by the shadows.</td>', 'Love the symmetry created by the shadows.', '2007-02-03 10:17:05.000000', NULL, 0),
