(3325701, 455488, 12611, '<td valign="top">Terrific execution and fantastic imagination. I guess one could nit-pick the details but thats not really necessary or fair, just a great entry.</td>', 'Terrific execution and fantastic imagination. I guess one could nit-pick the details but thats not really necessary or fair, just a great entry.', '2007-02-04 10:51:53.000000', NULL, 0),
(3326980, 455126, 73499, '<td valign="top">Well deserved!</td>', 'Well deserved!', '2007-02-04 18:22:50.000000', NULL, 0),
